const parseSafe = (input) => {
  if (!input) return {};
  if (typeof input === "object") return input;
  try { return JSON.parse(String(input).replace(/```json|```/g, "").trim()); }
  catch (e) { return {}; }
};

// ── BBB Only batch (new) ───────────────────────────────────────────────────────
function computeBBB(res, row_number) {
  // Fail-only gate: Fail ONLY when the model explicitly says "fail".
  // Missing key / garbage / degeneration = no affirmative Fail condition matched → Pass.
  const bbbRaw = String(res.blank_blur_back || "").toLowerCase();
  const bbbVal = bbbRaw.includes("fail") ? "Fail" : "Pass";
  return {
    row_number,
    blank_blur_back: bbbVal,
    wb_type: "bbb"
  };
}

// ── OCR: 3-tier matching (G1) ──────────────────────────────────────────────────
function computeOCR(res, tracking_no, row_number) {
  if (!row_number) throw new Error("computeOCR: row_number missing");
  const auth_check = res.step1_label_detected || "No";
  const extracted_raw = String(res.step2_extracted_full_id || "");

  const cleanID = (id) => String(id).replace(/[^A-Z0-9]/gi, "").toUpperCase();
  const target_clean = cleanID(tracking_no);
  const extracted_clean = cleanID(extracted_raw);

  const normalizeAmbiguous = (id) => String(id)
    .replace(/[5S]/g, "S").replace(/[2Z]/g, "Z").replace(/[0O]/g, "O")
    .replace(/[1IL]/g, "I").replace(/[8B]/g, "B");

  const ambiguousPairs = {
    "S": ["5"], "5": ["S"], "Z": ["2"], "2": ["Z"],
    "O": ["0"], "0": ["O"],
    "I": ["1", "L"], "1": ["I", "L"], "L": ["I", "1"],
    "B": ["8"], "8": ["B", "6"], "6": ["8", "G"], "G": ["6"],
  };

  const getEditDistance = (a, b) => {
    if (a.length === 0) return b.length;
    if (b.length === 0) return a.length;
    const matrix = [];
    for (let i = 0; i <= b.length; i++) matrix[i] = [i];
    for (let j = 0; j <= a.length; j++) matrix[0][j] = j;
    for (let i = 1; i <= b.length; i++) {
      for (let j = 1; j <= a.length; j++) {
        const cA = a.charAt(j - 1);
        const cB = b.charAt(i - 1);
        let subCost = 1;
        if (cA === cB) subCost = 0;
        else if (ambiguousPairs[cA] && ambiguousPairs[cA].includes(cB)) subCost = 0;
        matrix[i][j] = Math.min(matrix[i - 1][j - 1] + subCost, Math.min(matrix[i][j - 1] + 1, matrix[i - 1][j] + 1));
      }
    }
    return matrix[b.length][a.length];
  };

  let awb_match = "Fail";
  if (extracted_clean && extracted_clean !== "UNREADABLE" && extracted_clean.length >= 4) {
    if (target_clean.endsWith(extracted_clean.slice(-4)) || extracted_clean.endsWith(target_clean.slice(-4))) {
      awb_match = "Pass";
    } else {
      const normT = normalizeAmbiguous(target_clean);
      const normE = normalizeAmbiguous(extracted_clean);
      if (normT.endsWith(normE.slice(-4)) || normE.endsWith(normT.slice(-4))) {
        awb_match = "Pass";
      } else {
        const typos = getEditDistance(target_clean, extracted_clean);
        if (target_clean.length >= 8 && typos <= 2) awb_match = "Pass";
      }
    }
  }

  const isAuthPass = auth_check.toLowerCase().includes("pass") || auth_check.toLowerCase().includes("yes");

  // Quality gate removed — N/A for bbb=Fail rows is applied by the Reconcile stage (bbb column).
  const awbVal = (isAuthPass && awb_match === "Pass") ? "Pass" : "Fail";
  const parcelVal = awbVal;

  return {
    row_number,
    awb: awbVal,
    parcel: parcelVal,
    call_log: "N/A",   // not applicable to OCR group
    location: "N/A",
    vehicle: "N/A",
    external_factor: "N/A",
    wb_type: "ocr"
    // blank_blur_back written only by standalone BBB batch
  };
}

// ── Call groups: date+duration+evidence_type+chat ──────────────────────────────
function parseDuration(val) {
  if (typeof val === "number") return val;
  const s = String(val || "0").trim();
  const parts = s.split(":").map(Number);
  if (parts.length === 2) return (parts[0] * 60) + parts[1];
  if (parts.length === 3) return (parts[0] * 3600) + (parts[1] * 60) + parts[2];
  return parseFloat(s) || 0;
}

function extractUrlDate(url) {
  const m = String(url).match(/\/downloads\/(\d{4})\/(\d{2})\/(\d{2})\//);
  return m ? `${m[1]}-${m[2]}-${m[3]}` : "";
}

// ── shared precondition: the identified evidence screenshot's upload date must match on_hold_date ──
// used by both call_log (evalCallLog) and chat (computeCall) paths — same rule, same field (call_screenshot_index).
function screenshotDateMatches(res, row) {
  const allUrls = [row.image_url_1, row.image_url_2, row.image_url_3];
  const csIdx = Math.max(1, Math.min(3, parseInt(res.call_screenshot_index) || 1)) - 1;
  const url = allUrls[csIdx] || row.image_url_1 || "";
  const urlDate = extractUrlDate(url);
  const sysDate = String(row.on_hold_date || "").trim().slice(0, 10);
  return !!(urlDate && sysDate && urlDate === sysDate);
}

// ── call_log rules per reason code — OUTGOING calls only, phone + date must match ──
// answered = duration >= 6s ; attempt = duration < 6s (missed 0s OR short 1-5s)
// 103 = lenient (any connected outgoing call = Pass - รับสาย)
// 102 = inverted (answered >=6s = Fail - รับสาย ; >=2 attempts = Pass - ไม่รับสาย)
// standard (101,104,105,109,110,131,132,133,134): answered>=1 -> Pass-รับสาย; >=2 attempts -> Pass-ไม่รับสาย; else Fail
function evalCallLog(res, row, type) {
  const code = String(row.on_hold_reason_code || "").trim();

  // date precondition: call screenshot date must match on_hold_date
  if (!screenshotDateMatches(res, row)) return "Fail";

  const phone4 = String(row.contact_phone_masked || "").replace(/\D/g, "").slice(-4);
  const rawEntries = Array.isArray(res.call_entries) ? res.call_entries : [];
  // Defense-in-depth: prompt already asks the model to date-filter call_entries at extraction time,
  // but that has proven unreliable (wrong-day entries slipping through). Re-filter here on entry_date
  // vs on_hold_date. If entry_date is missing/empty (older cached data, or model non-compliance),
  // keep the entry as-is to preserve current behavior exactly.
  const onHoldDate = String(row.on_hold_date || "").trim().slice(0, 10);
  const entries = rawEntries.filter(e => !e.entry_date || e.entry_date === onHoldDate);

  let answered = 0, attempts = 0, connected = 0;
  for (const e of entries) {
    if (String(e.direction || "").toLowerCase() !== "outgoing") continue; // incoming/unknown ignored
    const phoneKey = ("phone_last4" in e && e.phone_last4) ? "phone_last4" : Object.keys(e).find(k => /^phone_last/i.test(k) && e[k]);
    const p = String(phoneKey ? e[phoneKey] : "").replace(/\D/g, "").slice(-4);
    if (!(phone4 && p && p === phone4)) continue;                          // phone must match
    const cnt = Math.max(1, Math.round(Number(e.count) || 1));            // Android "(N)" repeat-count badge; default 1 if absent/0/non-numeric
    const dur = parseDuration(e.duration_sec);
    if (dur >= 6) { answered += cnt; connected += cnt; }
    else if (dur >= 1) { attempts += cnt; connected += cnt; }  // short 1-5s = attempt (also connected for 103)
    else { attempts += cnt; }                             // 0s / missed = attempt
  }

  if (code === "103") return connected >= 1 ? "Pass - รับสาย" : "Fail";

  const inverted = code === "102" || (!code && type === "call_no_ans");
  if (inverted) {
    if (answered >= 1) return "Fail - รับสาย";
    if (attempts >= 2) return "Pass - ไม่รับสาย";
    return "Fail";
  }

  // standard rule
  if (answered >= 1) return "Pass - รับสาย";
  if (attempts >= 2) return "Pass - ไม่รับสาย";
  return "Fail";
}

function computeCall(res, type, row) {
  const rowNum = row.row_number;

  // Quality gate removed — N/A for bbb=Fail rows is applied by the Reconcile stage (bbb column).

  // ── evidence_type routing ──────────────────────────────────────────────────
  const evidenceType = String(res.evidence_type || "call_log").toLowerCase();
  let callLog;

  if (evidenceType === "chat") {
    // Same upload-date precondition as call_log — the chat screenshot's date must match on_hold_date.
    if (!screenshotDateMatches(res, row)) {
      callLog = "Fail";
    } else if (res.chat_relevant === true) {
      callLog = "Pass - in app chat";
    } else if (res.chat_relevant === false) {
      // null/undefined means relevance was never evaluated (often a misdetection) → plain Fail, handled below.
      callLog = "Fail - in app chat";
    } else {
      callLog = "Fail";
    }
  } else if (evidenceType === "none") {
    callLog = "Fail";
  } else {
    // call_log evidence — per reason-code rules, outgoing calls only
    callLog = evalCallLog(res, row, type);
  }

  const out = {
    row_number: rowNum,
    awb: "N/A",
    parcel: "N/A",
    // blank_blur_back intentionally omitted — written by BBB batch
    call_log: callLog,
    location: "N/A",
    vehicle: "N/A",
    external_factor: "N/A",
    wb_type: type
  };

  if (type === "call_loc") {
    out.location = String(res.location_valid || "").toLowerCase().includes("pass") ? "Pass" : "Fail";
  }
  if (type === "call_veh") {
    out.vehicle = String(res.vehicle_valid || "").toLowerCase().includes("pass") ? "Pass" : "Fail";
  }
  if (type === "call_ext") {
    out.external_factor = String(res.external_valid || "").toLowerCase().includes("pass") ? "Pass" : "Fail";
  }

  return out;
}

// ── Hybrid picker: combine classify + assume-call + assume-chat results ────────
// classify decides evidence_type; the matching "assume" variant supplies call_entries /
// chat_relevant / location_valid / vehicle_valid / external_valid (Step 3 is independent
// of the call/chat decision, so either variant's Step 3 answer is usable as a fallback).
function pickHybridResult(classify, ascall, aschat) {
  const evType = String((classify && classify.evidence_type) || "").toLowerCase();
  if (evType === "call_log" && ascall) {
    return Object.assign({}, ascall, { evidence_type: "call_log" });
  }
  if (evType === "chat" && aschat) {
    return Object.assign({}, aschat, { evidence_type: "chat" });
  }
  // "none", or classify missing/failed to parse, or the matching assume-variant is missing
  // (e.g. dropped by an upstream error) -> force Fail via evidence_type "none", but keep
  // whichever Step 3 field (location/vehicle/external) is available from either variant.
  const fallback = ascall || aschat || {};
  return Object.assign({}, fallback, { evidence_type: "none" });
}

// ── External obstruction (G5) ──────────────────────────────────────────────────
function computeExt(res, row_number) {
  if (!row_number) throw new Error("computeExt: row_number missing");
  // Quality gate removed — N/A for bbb=Fail rows is applied by the Reconcile stage (bbb column).
  return {
    row_number,
    awb: "N/A", parcel: "N/A",
    call_log: "N/A", location: "N/A", vehicle: "N/A",
    external_factor: String(res.external_valid || "").toLowerCase().includes("pass") ? "Pass" : "Fail",
    wb_type: "ext"
  };
}

// ── Fuel gauge (G8) ────────────────────────────────────────────────────────────
function computeFuel(res, row) {
  const rowNum = row.row_number;
  const sysDate = String(row.on_hold_date || "").trim().slice(0, 10);
  const tsDate = String(res.extracted_timestamp_date || "").trim().slice(0, 10);
  const dateValid = !!(tsDate && sysDate && tsDate === sysDate);
  const fuelOk = String(res.fuel_valid || "").toLowerCase().includes("pass");
  // Quality gate removed — N/A for bbb=Fail rows is applied by the Reconcile stage (bbb column).
  return {
    row_number: rowNum,
    awb: "N/A", parcel: "N/A",
    call_log: "N/A", location: "N/A", vehicle: "N/A",
    external_factor: (dateValid && fuelOk) ? "Pass" : "Fail",
    wb_type: "fuel"
  };
}

// ── Main ───────────────────────────────────────────────────────────────────────
const raw = String($json.jsonl || "");
const src = $('Read Source').all().map(i => i.json);
const srcMap = {};
for (const r of src) srcMap[String(r.row_number)] = r;

const CALL_TYPES = new Set(["call", "call_loc", "call_veh", "call_ext", "call_no_ans"]);

// hybrid call-type groups: key = `${baseType}|${rowStr}` -> { baseType, row, classify, ascall, aschat }
const callGroups = {};

const out = [];
for (const line of raw.split("\n")) {
  if (!line.trim()) continue;
  let obj; try { obj = JSON.parse(line); } catch (e) { continue; }
  const cid = String(obj.custom_id || "");
  const sep = cid.indexOf("|");
  if (sep === -1) continue;
  const typeRaw = cid.slice(0, sep);
  const rowStr = cid.slice(sep + 1);
  if (!rowStr) continue;
  if (obj.error || !obj.response || obj.response.status_code !== 200) continue;
  let content = "";
  try { content = obj.response.body.choices[0].message.content; } catch (e) {}
  const res = parseSafe(content);
  const row = srcMap[rowStr] || {};
  const rowNum = Number(rowStr) || rowStr;
  row.row_number = rowNum;

  if (typeRaw.includes("::")) {
    // hybrid call-type line: "<baseType>::classify|<row>" / "::ascall|<row>" / "::aschat|<row>"
    const [baseType, stage] = typeRaw.split("::");
    const key = `${baseType}|${rowStr}`;
    if (!callGroups[key]) callGroups[key] = { baseType, row };
    callGroups[key][stage] = res;
    continue;
  }

  if (typeRaw === "bbb") {
    out.push({ json: computeBBB(res, rowNum) });
  } else if (typeRaw === "ocr") {
    out.push({ json: computeOCR(res, String(row.tracking_no || ""), rowNum) });
  } else if (typeRaw === "ext") {
    out.push({ json: computeExt(res, rowNum) });
  } else if (typeRaw === "fuel") {
    out.push({ json: computeFuel(res, row) });
  }
  // (CALL_TYPES no longer arrive as plain lines — always routed through the "::" branch above)
}

// finalize hybrid call-type groups now that classify/ascall/aschat have been collected
for (const key in callGroups) {
  const g = callGroups[key];
  const finalRes = pickHybridResult(g.classify, g.ascall, g.aschat);
  out.push({ json: computeCall(finalRes, g.baseType, g.row) });
}

return out;

const out = [];
for (const it of $input.all()) {
  const r = it.json;
  const bbb = String(r.blank_blur_back || "").toLowerCase();
  if (!bbb.includes("fail")) continue;
  out.push({ json: {
    row_number: r.row_number,
    awb: "N/A", parcel: "N/A", call_log: "N/A",
    location: "N/A", vehicle: "N/A", external_factor: "N/A"
  }});
}
return out;
